using namespace std;

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    cin >> n;

    vector<int> last(100001, -1);
    int left = 0, ans = 0;

    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        if (last[x] >= left) {
            left = last[x] + 1;
        }
        last[x] = i;
        ans = max(ans, i - left + 1);
    }

    cout << ans << "\n";
    return 0;
}
